18	      if (filterType !== 'ALL' && e.type !== filterType) return false;
19	      if (filterPriority !== 'ALL' && e.priority !== filterPriority) return false;
20	      if (filterProject !== 'ALL' && e.project_slug !== filterProject) return false;
21	      return true;
22	    });
23	
24	    if (!filtered.length) {
25	      return '<p class="text-muted mt-16">No insights found.</p>';
26	    }
27	
28	    return filtered.map(function (e) {
29	      var priorityClass = e.priority ? ' priority-' + e.priority : '';
30	      var contextHtml = '';
31	      if (e.context && typeof e.context === 'object') {
32	        var ctxItems = Object.entries(e.context).map(function (pair) {
33	          return '<span><strong>' + escapeHtml(pair[0]) + ':</strong> ' + escapeHtml(String(pair[1])) + '</span>';
34	        }).join('<br>');
35	        contextHtml =
36	          '<div class="comment-context">' +
37	            ctxItems +
38	          '</div>';
39	      }
40	      return '<div class="comment-card' + priorityClass + '">' +
41	        '<div class="comment-meta">' +
42	          '<a href="#/projects/' + encodeURIComponent(e.project_slug) + '">' + escapeHtml(e.project_slug) + '</a>' +
43	          ' &mdash; ' +
