46	          ' <span>' + escapeHtml(formatDate(e.timestamp)) + '</span>' +
47	        '</div>' +
48	        '<div class="comment-body">' + escapeHtml(e.note || '') + '</div>' +
49	        contextHtml +
50	      '</div>';
51	    }).join('');
52	  }
